pub fn OSGetStackPointer<'a>(ctx: &'a Ctx) -> u32 {
    // Transliterated from its machine code: its source is assembly.
    ().put_regs(ctx);
    asm_OSGetStackPointer(ctx);
    Ret::get(ctx)
}

fn asm_OSGetStackPointer(ctx: &Ctx) {
    let g = &ctx.regs.gpr;
    let f = &ctx.regs.fpr;
    let lr0 = ctx.regs.lr.get();
    let _ = (g, f, lr0);
    // mr r3, r1
    {
        let v = g[1].get() | g[1].get();
        g[3].set(v);
    }
    // blr
    let to = ctx.regs.lr.get() & !3;
    if to != lr0 & !3 {
        c::tail_call(ctx, to);
    }
    return;
}

pub fn OSClearContext<'a>(ctx: &'a Ctx, context: OSContext<'a>) {
    let mut context = context;
    (context).set_mode((0_i32 as u16));
    (context).set_state((0_i32 as u16));
    if Handle::addr(context) == Handle::addr(fns::__OSFPUContext(ctx).get()) {
        fns::__OSFPUContext(ctx).set(null::<OSContext<'a>>(ctx));
    }
}

pub fn OSInitContext<'a>(ctx: &'a Ctx, a0: OSContext<'a>, a1: u32, a2: u32) {
    // Transliterated from its machine code: its source is assembly.
    (a0, a1, a2).put_regs(ctx);
    asm_OSInitContext(ctx);
}

