pub fn OSDumpContext<'a>(ctx: &'a Ctx, context: OSContext<'a>) {
    let __frame = ctx.stack_frame(0x2f8);
    let fpuContext: OSContext<'a> = frame_at(ctx, &__frame, 0x8);
    let mut context = context;
    let mut i: u32 = 0;
    let mut p: Val<'a, u32> = null(ctx);
    fns::OSReport(
        ctx,
        cstr(ctx, 0x80401e20),
        &[VarArg::Int(Handle::addr(context))],
    );
    {
        i = (0_i32 as u32);
        'l1: while i < (16_i32 as u32) {
            'c2: {
                fns::OSReport(
                    ctx,
                    cstr(ctx, 0x80401e64),
                    &[
                        VarArg::Int(i as u32),
                        VarArg::Int((context).gpr().at((i as i32)).get() as u32),
                        VarArg::Int((context).gpr().at((i as i32)).get() as u32),
                        VarArg::Int(i.wrapping_add((16_i32 as u32)) as u32),
                        VarArg::Int(
                            (context)
                                .gpr()
                                .at((i.wrapping_add((16_i32 as u32)) as i32))
                                .get() as u32,
                        ),
                        VarArg::Int(
                            (context)
                                .gpr()
                                .at((i.wrapping_add((16_i32 as u32)) as i32))
                                .get() as u32,
                        ),
                    ],
                );
            }
            i = i.wrapping_add(1);
        }
    }
    fns::OSReport(
        ctx,
        cstr(ctx, 0x80401e94),
        &[
            VarArg::Int((context).lr() as u32),
            VarArg::Int((context).cr() as u32),
        ],
    );
    fns::OSReport(
        ctx,
        cstr(ctx, 0x80401ec4),
        &[
            VarArg::Int((context).srr0() as u32),
            VarArg::Int((context).srr1() as u32),
        ],
    );
    fns::OSReport(ctx, cstr(ctx, 0x80401ef4), &[]);
    {
        i = (0_i32 as u32);
        'l3: while i < (4_i32 as u32) {
            'c4: {
                fns::OSReport(
                    ctx,
                    cstr(ctx, 0x80401f08),
                    &[
                        VarArg::Int(i as u32),
                        VarArg::Int((context).gqr().at((i as i32)).get() as u32),
                        VarArg::Int(i.wrapping_add((4_i32 as u32)) as u32),
                        VarArg::Int(
                            (context)
                                .gqr()
                                .at((i.wrapping_add((4_i32 as u32)) as i32))
                                .get() as u32,
                        ),
                    ],
                );
            }
            i = i.wrapping_add(1);
        }
    }
    if ((((context).state() as u32) & 1_u32) != 0) {
        let mut currentContext: OSContext<'a> = null(ctx);
        let mut enabled: i32 = 0;
        enabled = fns::OSDisableInterrupts(ctx);
        currentContext = inl_OSGetCurrentContext_unfused(ctx);
        inl_OSClearContext_unfused(ctx, fpuContext);
        fns::OSSetCurrentContext(ctx, fpuContext);
        fns::OSReport(ctx, cstr(ctx, 0x80401f2c), &[]);
        {
            i = (0_i32 as u32);
            'l5: while i < (32_i32 as u32) {
                'c6: {
                    fns::OSReport(
                        ctx,
                        cstr(ctx, 0x80401f40),
                        &[
                            VarArg::Int(i as u32),
                            VarArg::Int(fns::__cvt_fp2unsigned(
                                ctx,
                                (context).fpr().at((i as i32)).get(),
                            ) as u32),
                            VarArg::Int(i.wrapping_add((1_i32 as u32)) as u32),
                            VarArg::Int(fns::__cvt_fp2unsigned(
                                ctx,
                                (context)
                                    .fpr()
                                    .at((i.wrapping_add((1_i32 as u32)) as i32))
                                    .get(),
                            ) as u32),
                        ],
                    );
                }
                i = i.wrapping_add((2_i32 as u32));
            }
        }
        fns::OSReport(ctx, cstr(ctx, 0x80401f5c), &[]);
        {
            i = (0_i32 as u32);
            'l7: while i < (32_i32 as u32) {
                'c8: {
                    fns::OSReport(
                        ctx,
                        cstr(ctx, 0x80401f70),
                        &[
                            VarArg::Int(i as u32),
                            VarArg::Int(fns::__cvt_fp2unsigned(
                                ctx,
                                (context).psf().at((i as i32)).get(),
                            ) as u32),
                            VarArg::Int(i.wrapping_add((1_i32 as u32)) as u32),
                            VarArg::Int(fns::__cvt_fp2unsigned(
                                ctx,
                                (context)
                                    .psf()
                                    .at((i.wrapping_add((1_i32 as u32)) as i32))
                                    .get(),
                            ) as u32),
                        ],
                    );
                }
                i = i.wrapping_add((2_i32 as u32));
            }
        }
        inl_OSClearContext_unfused(ctx, fpuContext);
        fns::OSSetCurrentContext(ctx, currentContext);
        let _ = fns::OSRestoreInterrupts(ctx, enabled);
    }
    fns::OSReport(ctx, cstr(ctx, 0x80401f90), &[]);
    {
        i = (0_i32 as u32);
        p = ptr::<Val<'a, u32>>(ctx, (context).gpr().at(1_i32).get() as u32);
        'l9: while ((!Handle::is_null(p)) && (Handle::addr(p) != 0xffffffff_u32))
            && ({
                let __t1 = i;
                i = i.wrapping_add(1);
                __t1
            } < (16_i32 as u32))
        {
            'c10: {
                fns::OSReport(
                    ctx,
                    cstr(ctx, 0x80401fb8),
                    &[
                        VarArg::Int(Handle::addr(p)),
                        VarArg::Int((Handle::add(p, 0_i32)).get() as u32),
                        VarArg::Int((Handle::add(p, 1_i32)).get() as u32),
                    ],
                );
            }
            p = ptr::<Val<'a, u32>>(ctx, (p).get() as u32);
        }
    }
}

pub fn OSSwitchFPUContext<'a>(ctx: &'a Ctx, a0: u8, a1: OSContext<'a>) {
    // Transliterated from its machine code: its source is assembly.
    (a0, a1).put_regs(ctx);
    asm_OSSwitchFPUContext(ctx);
}

fn asm_OSSwitchFPUContext(ctx: &Ctx) {
    let g = &ctx.regs.gpr;
    let f = &ctx.regs.fpr;
    let lr0 = ctx.regs.lr.get();
    let _ = (g, f, lr0);
    let mut pc: u32 = 0x803455dc_u32;
    loop {
        match pc {
            0x803455dc_u32 => {
                // mfmsr r5
                g[5].set(ctx.regs.msr.get());
                // ori r5, r5, 0x2000
                g[5].set(g[5].get() | 0x2000_u32);
                // mtmsr r5
                ctx.set_msr(g[5].get());
                // isync
                // lwz r5, 0x19c(r4)
                {
                    let ea = g[4].get().wrapping_add(0x19c_u32);
                    g[5].set(ctx.read_u32(ea));
                }
                // ori r5, r5, 0x2000
                g[5].set(g[5].get() | 0x2000_u32);
                // mtsrr1 r5
                ctx.regs.set_spr(27, g[5].get());
                // lis r3, 0x8000
                g[3].set(0x80000000_u32);
                // lwz r5, 0xd8(r3)
                {
                    let ea = g[3].get().wrapping_add(0xd8_u32);
                    g[5].set(ctx.read_u32(ea));
                }
                // stw r4, 0xd8(r3)
                {
                    let ea = g[3].get().wrapping_add(0xd8_u32);
                    ctx.write_u32(ea, g[4].get());
                }
                // cmpw r5, r4
                {
                    let (x, y) = (g[5].get() as i32, g[4].get() as i32);
                    c::compare(ctx, 0, x < y, x > y);
                }
                // beq .L_8034561C
                if (c::cr_bit(ctx, 2) == true) {
                    pc = 0x8034561c_u32;
                    continue;
                }
                pc = 0x8034560c_u32;
            }
            0x8034560c_u32 => {
                // cmpwi r5, 0x0
                {
                    let (x, y) = (g[5].get() as i32, 0_i32);
                    c::compare(ctx, 0, x < y, x > y);
                }
                // beq .L_80345618
                if (c::cr_bit(ctx, 2) == true) {
                    pc = 0x80345618_u32;
                    continue;
                }
                pc = 0x80345614_u32;
            }
            0x80345614_u32 => {
                // bl __OSSaveFPUContext
                c::call(ctx, 0x80344f54_u32, 0x80345618_u32);
                pc = 0x80345618_u32;
            }
            0x80345618_u32 => {
                // bl __OSLoadFPUContext
                c::call(ctx, 0x80344e30_u32, 0x8034561c_u32);
                pc = 0x8034561c_u32;
            }
            0x8034561c_u32 => {
                // lwz r3, 0x80(r4)
                {
                    let ea = g[4].get().wrapping_add(0x80_u32);
                    g[3].set(ctx.read_u32(ea));
                }
                // mtcrf 255, r3
                {
                    let v = g[3].get();
                    c::set_cr_field(ctx, 0, v >> 28);
                    c::set_cr_field(ctx, 1, v >> 24);
                    c::set_cr_field(ctx, 2, v >> 20);
                    c::set_cr_field(ctx, 3, v >> 16);
                    c::set_cr_field(ctx, 4, v >> 12);
                    c::set_cr_field(ctx, 5, v >> 8);
                    c::set_cr_field(ctx, 6, v >> 4);
                    c::set_cr_field(ctx, 7, v >> 0);
                }
                // lwz r3, 0x84(r4)
                {
                    let ea = g[4].get().wrapping_add(0x84_u32);
                    g[3].set(ctx.read_u32(ea));
                }
                // mtlr r3
                ctx.regs.set_spr(8, g[3].get());
                // lwz r3, 0x198(r4)
                {
                    let ea = g[4].get().wrapping_add(0x198_u32);
                    g[3].set(ctx.read_u32(ea));
                }
                // mtsrr0 r3
                ctx.regs.set_spr(26, g[3].get());
                // lwz r3, 0x88(r4)
                {
                    let ea = g[4].get().wrapping_add(0x88_u32);
                    g[3].set(ctx.read_u32(ea));
                }
                // mtctr r3
                ctx.regs.set_spr(9, g[3].get());
                // lwz r3, 0x8c(r4)
                {
                    let ea = g[4].get().wrapping_add(0x8c_u32);
                    g[3].set(ctx.read_u32(ea));
                }
                // mtxer r3
                ctx.regs.set_spr(1, g[3].get());
                // lhz r3, 0x1a2(r4)
                {
                    let ea = g[4].get().wrapping_add(0x1a2_u32);
                    g[3].set(u32::from(ctx.read_u16(ea)));
                }
                // rlwinm r3, r3, 0, 31, 29
                {
                    let v = g[3].get().rotate_left(0) & 0xfffffffd_u32;
                    g[3].set(v);
                }
                // sth r3, 0x1a2(r4)
                {
                    let ea = g[4].get().wrapping_add(0x1a2_u32);
                    ctx.write_u16(ea, g[3].get() as u16);
                }
                // lwz r5, 0x14(r4)
                {
                    let ea = g[4].get().wrapping_add(0x14_u32);
                    g[5].set(ctx.read_u32(ea));
                }
                // lwz r3, 0xc(r4)
                {
                    let ea = g[4].get().wrapping_add(0xc_u32);
                    g[3].set(ctx.read_u32(ea));
                }
                // lwz r4, 0x10(r4)
                {
                    let ea = g[4].get().wrapping_add(0x10_u32);
                    g[4].set(ctx.read_u32(ea));
                }
                // rfi
                panic!("rfi at 0x8034565c: exceptions are not emulated");
                panic!("ran off the end of OSSwitchFPUContext");
            }
            _ => unreachable!("OSSwitchFPUContext: no block at {pc:#010x}"),
        }
    }
}

pub fn __OSContextInit<'a>(ctx: &'a Ctx) {
    let __frame = ctx.stack_frame(0x8);
    let _ = fns::__OSSetExceptionHandler(ctx, (7_i32 as u8), fnptr(ctx, 0x803455dc));
    fns::__OSFPUContext(ctx).set(null::<OSContext<'a>>(ctx));
    fns::DBPrintf(ctx, cstr(ctx, 0x80401fd4), &[]);
}

fn inl_OSGetCurrentContext_unfused<'a>(ctx: &'a Ctx) -> OSContext<'a> {
    return fns::__OSCurrentContext(ctx).get();
}

fn inl_OSClearContext_unfused<'a>(ctx: &'a Ctx, context: OSContext<'a>) {
    let mut context = context;
    (context).set_mode((0_i32 as u16));
    (context).set_state((0_i32 as u16));
    if Handle::addr(context) == Handle::addr(fns::__OSFPUContext(ctx).get()) {
        fns::__OSFPUContext(ctx).set(null::<OSContext<'a>>(ctx));
    }
}

